import numpy as np, torch, model
net = model.load()
print('existing grafts',len(net.grafts),[ (g.layer) for g in net.grafts])
base=list(net.grafts)
W=torch.tensor(np.load('c2p_detw.npy')); B0=float(np.load('c2p_detb.npy'))
def isbad(a,cn):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); th=-89+65*cn
    return (np.abs(ang-th)<13)&(np.linalg.norm(a,axis=1)>1.8)
class G:
    def __init__(s,layer,thr,vec,klo,khi): s.layer=layer; s.thr=thr; s.vec=torch.tensor(vec).float(); s.klo=klo; s.khi=khi
    def fires(s,feats,t):
        k=torch.round((1-t)*20)
        return ((feats['out_act']@W+B0)>s.thr)&(k>=s.klo)&(k<s.khi)
    def contribution(s,feats): return s.vec.expand(feats['x'].shape[0],2)
torch.manual_seed(4); N2=8000
c2=torch.rand(N2); xi2=torch.randn(N2,2); a0=np.asarray(model.decode(net,xi2,c2)); c2n=c2.numpy(); b0=isbad(a0,c2n)
ref=torch.tensor(a0[~b0][::2])
def offd(x):
    return torch.cdist(torch.tensor(x),ref).topk(5,largest=False).values[:,-1].numpy()
base_off=(offd(a0)>0.3).mean()
for thr,mag,kl,kh in [(1,3,8,13),(1,5,8,13),(1,8,8,13),(1,5,6,13),(2,8,8,13),(1,-5,8,13)]:
    net.grafts=base+[G('out',thr,[mag,0.0],kl,kh)]
    a1=np.asarray(model.decode(net,xi2,c2)); b1=isbad(a1,c2n)
    mv=np.linalg.norm(a1-a0,axis=1)>0.35
